package it.andreademartini.trading.paper.multi;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static it.andreademartini.trading.paper.patternv1.PatternPaperModel.*;
import static it.andreademartini.trading.backtest.patternv1.PatternV1TestSupport.engulfing;
import it.andreademartini.trading.paper.patternv1.*;
import it.andreademartini.trading.backtest.patternstable.PatternStableService;
import it.andreademartini.trading.orders.*;
import com.ib.client.*;
import java.math.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;

class MultiStrategyPaperRouterTest {
    final Instant now=Instant.now();final String account="DU_TEST_ALLOWED";
    PatternPaperBroker raw;Session a,b;MultiStrategyPaperRouter router;
    BigDecimal bd(long v){return BigDecimal.valueOf(v);}
    @BeforeEach void setup(){raw=mock(PatternPaperBroker.class);when(raw.connection()).thenReturn(new Connection(true,"127.0.0.1",4002,account,List.of(account),true,true,true,"Verified MOCK only",now,now,1));when(raw.limitations()).thenReturn(List.of());a=session();b=session();router=new MultiStrategyPaperRouter(raw,()->a,()->b,null,true);snapshot(0,10000);}
    Session session(){var s=new Session();s.account=account;s.frozen=new PatternStableService(null,null,null,null).version("2.1");s.strategyVersion=s.frozen.strategyVersion();s.configurationHash=s.frozen.configurationHash();return s;}
    SignalRecord signal(Session s,String id){var r=new SignalRecord();r.id=id;r.symbol="AAPL";r.mode="PAPER";r.status="SUBMITTED";r.generatedAt=now;r.signal=new PatternPaperPlanner(s.frozen).signals("AAPL",engulfing("AAPL"),1).getFirst();r.expectedEntry=bd(100);r.expectedStop=bd(98);r.expectedTarget=bd(106);r.entrySession=LocalDate.now();s.signals.add(r);return r;}
    OrderRecord order(Session s,int id,String signal,Role role,int quantity){var o=new OrderRecord();o.orderId=id;o.signalId=signal;o.symbol="AAPL";o.account=account;o.action=role==Role.ENTRY?"BUY":"SELL";o.role=role;o.quantity=quantity;o.clientOrderId=(s==a?"PV1:":"PV2:")+signal+":"+role;o.status="Submitted";o.createdAt=now;s.orders.add(o);return o;}
    ExecutionRecord fill(int id,String execution,int qty,Role role){return new ExecutionRecord(execution,null,id,10000+id,account,"AAPL",role==Role.ENTRY?"BUY":"SELL",bd(qty),bd(role==Role.ENTRY?100:98),now,role);}
    void entered(Session s,String signal,int id,int qty){signal(s,signal);order(s,id,signal,Role.ENTRY,qty);PatternPaperLedger.execution(s,fill(id,"entry-"+id,qty,Role.ENTRY));s.orders.getLast().status="Filled";}
    void snapshot(int qty,int funds){when(raw.reconcile()).thenReturn(new BrokerSnapshot(1,Instant.now(),qty==0?List.of():List.of(new BrokerPosition(account,"AAPL",bd(qty),bd(100))),List.of(),List.of(),List.of(),bd(funds),true,"Complete MOCK"));}
    IbkrOrderCommand command(int id,String signal,int qty,String role){var o=new com.ib.client.Order();o.account(account);o.orderRef("PV1:"+signal+":"+role);return new IbkrOrderCommand(id,null,signal,role,"AAPL",role.equals("ENTRY")?OrderSide.BUY:OrderSide.SELL,PaperOrderType.MARKET,null,null,qty,100.0,null,null,null,new Contract(),o);}
    @Test void sameDirectionPositionsAreAttributedAndStopClosesOnlyOwner(){entered(a,"v1",101,10);entered(b,"v2",201,8);snapshot(18,10000);assertTrue(router.view("PATTERN_V1").reconcile().complete());assertEquals(bd(10),router.view("PATTERN_V1").reconcile().positions().getFirst().quantity());assertEquals(bd(8),router.view("PATTERN_V2").reconcile().positions().getFirst().quantity());order(a,102,"v1",Role.STOP_LOSS,10);router.view("PATTERN_V1").place(command(102,"v1",10,"STOP_LOSS"));verify(raw).place(any());PatternPaperLedger.execution(a,fill(102,"stop-v1",10,Role.STOP_LOSS));assertEquals(0,a.trades.getFirst().remaining().signum());assertEquals(bd(8),b.trades.getFirst().remaining());snapshot(8,10000);assertTrue(router.view("PATTERN_V2").reconcile().complete());}
    @Test void partialExitsAndDuplicateFillsPreserveEachVirtualEquity(){entered(a,"v1",101,10);entered(b,"v2",201,8);order(a,102,"v1",Role.STOP_LOSS,10);var partial=fill(102,"partial",4,Role.STOP_LOSS);assertTrue(PatternPaperLedger.execution(a,partial));assertFalse(PatternPaperLedger.execution(a,partial));assertEquals(bd(6),a.trades.getFirst().remaining());assertEquals(bd(8),b.trades.getFirst().remaining());assertNotEquals(PatternPaperLedger.capital(a,now).equity(),PatternPaperLedger.capital(b,now).equity());assertEquals(bd(10000),PatternPaperLedger.capital(b,now).equity());snapshot(14,10000);assertTrue(router.view("PATTERN_V1").reconcile().complete());}
    @Test void cannotExitOtherStrategyQuantityOrUseItsOrderId(){entered(a,"v1",101,10);entered(b,"v2",201,8);snapshot(18,10000);router.view("PATTERN_V1").reconcile();order(a,102,"v1",Role.STOP_LOSS,10);assertThrows(IllegalStateException.class,()->router.view("PATTERN_V1").place(command(102,"v1",11,"STOP_LOSS")));assertThrows(IllegalStateException.class,()->router.view("PATTERN_V2").place(command(102,"v1",10,"STOP_LOSS")));verify(raw,never()).place(any());}
    @Test void oppositePendingDirectionIsRejectedBeforeAnyBracket(){var v1=signal(a,"v1");signal(b,"v2");order(b,201,"v2",Role.ENTRY,8).action="SELL";var e=assertThrows(IllegalStateException.class,()->router.view("PATTERN_V1").bracket(v1,10,account));assertEquals("MULTI_STRATEGY_POSITION_CONFLICT",e.getMessage());verify(raw,never()).bracket(any(),anyLong(),anyString());}
    @Test void productionSimultaneityRemainsDisabledEvenForSameDirection(){entered(b,"v2",201,8);var locked=new MultiStrategyPaperRouter(raw,()->a,()->b,null,false);var r=signal(a,"v1");var e=assertThrows(IllegalStateException.class,()->locked.view("PATTERN_V1").bracket(r,10,account));assertTrue(e.getMessage().contains("MULTI_STRATEGY_VALIDATION_REQUIRED"));assertFalse(locked.reconciliation().simultaneousCertified());}
    @Test void aggregatePendingReservationsCannotExceedActualFunds(){signal(a,"v1");order(a,101,"v1",Role.ENTRY,10);signal(b,"v2");order(b,201,"v2",Role.ENTRY,8);snapshot(0,1500);router.view("PATTERN_V1").reconcile();assertThrows(IllegalStateException.class,()->router.view("PATTERN_V1").place(command(101,"v1",10,"ENTRY")));verify(raw,never()).place(any());}
    @Test void callbackDrainIsRoutedExactlyOnceAndRecoveryNeverResubmits(){signal(a,"v1");order(a,101,"v1",Role.ENTRY,10);signal(b,"v2");order(b,201,"v2",Role.ENTRY,8);var one=fill(101,"one",10,Role.ENTRY);var two=fill(201,"two",8,Role.ENTRY);when(raw.drainExecutions()).thenReturn(List.of(one,two),List.of());assertEquals(List.of(one),router.view("PATTERN_V1").drainExecutions());assertEquals(List.of(two),router.view("PATTERN_V2").drainExecutions());assertTrue(router.view("PATTERN_V1").drainExecutions().isEmpty());PatternPaperLedger.execution(a,one);PatternPaperLedger.execution(b,two);snapshot(18,10000);var restarted=new MultiStrategyPaperRouter(raw,()->a,()->b,null,false);assertTrue(restarted.view("PATTERN_V1").reconcile().complete());verify(raw,never()).place(any());}
    @Test void unknownAccountQuantityAndDisconnectBlockMutation(){entered(a,"v1",101,10);snapshot(11,10000);assertFalse(router.view("PATTERN_V1").reconcile().complete());order(a,102,"v1",Role.STOP_LOSS,10);assertThrows(IllegalStateException.class,()->router.view("PATTERN_V1").place(command(102,"v1",10,"STOP_LOSS")));when(raw.connection()).thenReturn(new Connection(false,"localhost",4002,account,List.of(account),false,false,false,"Disconnected",now,now,2));assertThrows(IllegalStateException.class,()->router.view("PATTERN_V1").place(command(102,"v1",10,"STOP_LOSS")));verify(raw,never()).place(any());}
    @Test void liveAccountAndResearchStrategyHaveNoWritePath(){assertThrows(IllegalArgumentException.class,()->router.view("PATTERN_V3"));entered(a,"v1",101,10);snapshot(10,10000);router.view("PATTERN_V1").reconcile();order(a,102,"v1",Role.STOP_LOSS,10);when(raw.connection()).thenReturn(new Connection(true,"localhost",4002,"U_LIVE",List.of("U_LIVE"),false,true,true,"Not PAPER",now,now,1));assertThrows(IllegalStateException.class,()->router.view("PATTERN_V1").place(command(102,"v1",10,"STOP_LOSS")));verify(raw,never()).place(any());}
    @Test void shadowOnlyCannotBecomePaperComparison(){a.activationDate=b.activationDate=LocalDate.now();assertFalse(PaperDeskService.compare(a,b,null,null).available());assertThrows(IllegalArgumentException.class,()->PaperDeskService.compare(a,b,now,now.minusSeconds(1)));}
    @Test void uncertifiedAccountCashBudgetAlsoPreventsUnverifiedSingleStrategyEntry(){var locked=new MultiStrategyPaperRouter(raw,()->a,()->b,null,false);var e=assertThrows(IllegalStateException.class,()->locked.view("PATTERN_V1").bracket(signal(a,"v1"),10,account));assertTrue(e.getMessage().contains("ACCOUNT_CASH_BUDGET_UNVERIFIED"));assertTrue(locked.view("PATTERN_V1").limitations().stream().anyMatch(v->v.contains("ACCOUNT_CASH_BUDGET_UNVERIFIED")));verify(raw,never()).bracket(any(),anyLong(),anyString());}
}
